PROGRAM elevator
VAR_INPUT
    CallUp : BOOL;
    CallDown : BOOL;
    DoorClosed : BOOL;
    AtTop : BOOL;
    AtBottom : BOOL;
END_VAR
VAR_OUTPUT
    MotorUp : BOOL;
    MotorDown : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

CASE State OF
    0:  // At-bottom
        IF CallUp AND DoorClosed THEN
            State := 1;
        ELSIF NOT AtBottom THEN
            MotorDown := TRUE;
        ELSE
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;

    1:  // Moving-up
        IF Not CallUp OR AtTop OR NOT DoorClosed THEN
            State := AtTop AND DoorClosed AND CallUp ? 2 : 0;
        ELSIF DoorClosed THEN
            MotorUp := TRUE;
            MotorDown := FALSE;
        END_IF;

    2:  // At-top
        IF CallDown AND DoorClosed THEN
            State := 3;
        ELSIF NOT AtTop THEN
            MotorUp := TRUE;
        ELSE
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;

    3:  // Moving-down
        IF Not CallDown OR AtBottom OR NOT DoorClosed THEN
            State := AtBottom AND DoorClosed AND CallDown ? 0 : 2;
        ELSIF DoorClosed THEN
            MotorUp := FALSE;
            MotorDown := TRUE;
        END_IF;
END_CASE;

END_PROGRAM

