PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME literal := T#3s;
END_VAR

CASE State OF
    0: // Idle
        IF EStop OR (NOT StartBatch) THEN
            State := 0;
        ELSIF Level >= LVL_HIGH AND Level >= LIQ_MIN THEN
            State := 1;
        ELSIF Level < LVL_LOW AND Level >= LIQ_MIN THEN
            State := 4;
        END_IF;

    1: // Fill
        IF EStop OR Level >= LVL_HIGH OR Level < LIQ_MIN THEN
            State := 0;
        ELSE
            FillValve := TRUE;
        END_IF;

    2: // Heat
        IF EStop OR Level < LIQ_MIN THEN
            State := 0;
        ELSIF Temp >= TEMP_SET THEN
            State := 3;
