PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME literal := T#3s;
END_VAR

CASE State OF
    0:  // Idle
        IF EStop OR NOT StartBatch THEN
            State := 0;
        ELSIF Level >= LIQ_MIN AND Level < LVL_HIGH THEN
            State := 1;
        END_IF;

    1:  // Fill
        IF EStop THEN
            State := 0;
        ELSIF Level >= LVL_HIGH THEN
            State := 2;
        END_IF;
        FillValve := EStop AND (Level < LVL_HIGH);
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;

    2:  // Heat
        IF EStop THEN
            State := 0;
        ELSIF Level >= LIQ_MIN AND Temp >= TEMP_SET AND Level < LVL_HIGH THEN
            State := 3;
        END_IF;
        FillValve := FALSE;
        Heater := EStop AND (Temp < TEMP_SET) AND (Level >= LIQ_MIN);
        Agitator := EStop AND (Level >= LIQ_MIN);
        DrainValve := FALSE;

    3:  // React
        IF EStop THEN
            State := 0;
        ELSIF TimeElapsed >= PT_REACT THEN
            State := 4;
        END_IF;
        FillValve := FALSE;
        Heater := EStop AND (Temp < TEMP_SET) AND (Level >= LIQ_MIN);
        Agitator := EStop AND (Level >= LIQ_MIN);
        DrainValve := FALSE;

    4:  // Drain
        IF EStop OR (Level <= LVL_LOW) THEN
            State := 0;
        END_IF;
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := EStop AND (Level > LVL_LOW);
END_CASE;

END_PROGRAM

