VAR_OUTPUT
    Fan     : BOOL;
    Fuel    : BOOL;
    Ignition : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_PURGE : TIME := T#3s;
    PT_IGN : TIME := T#2s;
END_VAR

CASE State OF
    0:  // Off
        IF (NOT EStop) OR StopPB OR StartPB THEN
            State := 0;
        ELSIF EStop AND StartPB THEN
            State := 1;
        END_IF;
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;

    1:  // Purge
        IF (NOT EStop) OR StopPB THEN
            State := 0;
        ELSIF Timer1.T >= PT_PURGE THEN
            State := 2;
        END_IF;
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        Timer1(IN := TRUE, PT := PT_PURGE);

    2:  // Ignite
        IF (NOT EStop) OR StopPB OR (NOT Flame) THEN
            State := 0;
        ELSIF Timer2.T >= PT_IGN THEN
            State := 3;
        END_IF;
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        Timer2(IN := TRUE, PT := PT_IGN);

    3:  // Run
        IF (NOT EStop) OR StopPB OR (NOT Flame) THEN
            State := 0;
        END_IF;
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
END_CASE;

END_PROGRAM

